<script setup lang="ts">import type{Company}from '@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';import CompanyCard from'./CompanyCard.vue';const items=ref<Company[]>([]);const keyword=ref('');const loading=ref(false);async function load(){loading.value=true;const term=keyword.value.trim();items.value=(await repository.companies.list({...term?{keyword:term}:{},page:1,pageSize:24})).items;loading.value=false}onMounted(load)</script>
<template><section class="cl-page cl-container"><header class="directory-head"><div><p>企业招聘信息库</p><h1>认识公司，再选择机会</h1></div><form @submit.prevent="load"><input v-model="keyword" aria-label="搜索公司" placeholder="搜索公司或行业"/><button class="cl-primary-button">搜索</button></form></header><p v-if="loading">正在加载公司…</p><div v-else class="directory-grid"><CompanyCard v-for="company in items" :key="company.id" :company="company"/></div></section></template>
<style scoped>.directory-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:28px}.directory-head p{margin-bottom:4px;color:var(--cl-primary);font-weight:700}.directory-head h1{margin:0;color:var(--cl-text-strong);font-size:38px;letter-spacing:-.04em}.directory-head form{display:flex;gap:8px}.directory-head input{height:42px;min-width:280px;padding:0 13px;border:1px solid var(--cl-border);border-radius:8px;background:var(--cl-surface)}.directory-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}@media(max-width:850px){.directory-head{align-items:start;flex-direction:column}.directory-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:570px){.directory-head form{width:100%;flex-direction:column}.directory-head input{min-width:0}.directory-grid{grid-template-columns:1fr}}</style>
